// beacon-chain/sync/batch_verifier.go:verifyKzgBatch
func verifyKzgBatch(kzgBatch []*kzgVerifier) {
	if len(kzgBatch) == 0 { return }
	allDataColumns := make([]blocks.RODataColumn, 0, len(kzgBatch))
	for _, kzgVerifier := range kzgBatch {
		allDataColumns = append(allDataColumns, kzgVerifier.dataColumns...)
	}
	var verificationErr error
	err := peerdas.VerifyDataColumnsSidecarKZGProofs(allDataColumns)
	if err != nil {
		verificationErr = errors.Wrap(err, "batch KZG verification failed")
	}
	// Send the SAME error to ALL verifiers - shared contamination
	for _, verifier := range kzgBatch {
		verifier.resChan <- verificationErr
	}
}

func VerifyCellKZGProofBatch(commitmentsBytes []Bytes48, cellIndices []uint64, cells []Cell, proofsBytes []Bytes48) (bool, error) {
	ckzgCells := make([]ckzg4844.Cell, len(cells))
	for i := range cells {
		ckzgCells[i] = ckzg4844.Cell(cells[i])
	}
	return ckzg4844.VerifyCellKZGProofBatch(commitmentsBytes, cellIndices, ckzgCells, proofsBytes)
}
// This is a pure pass-through. hash_to_bls_field is implemented in the c-kzg C library.

// The Fiat-Shamir challenge computation (in c-kzg library) binds:
// SHA-256(domain_separator || FIELD_ELEMENTS_PER_BLOB || FIELD_ELEMENTS_PER_CELL ||
//         num_commitments || num_cells ||
//         all_unique_commitment_bytes... ||
//         per_cell: commitment_index || cell_index || cell_data || proof...)
// Go wrapper is a pure pass-through: all 4 arrays passed unchanged to C library.

// Attacker controls P2P DataColumnSidecar fields: KzgCommitments[], Column[] (cells), KzgProofs[], Index
// These map directly to: commitments, cells, proofs, cell_indices in VerifyDataColumnsSidecarKZGProofs
// The challenge r = SHA256(domain || constants || num_commitments || num_cells || all_inputs...)
// Full preimage control by attacker; zero SHA-256 output control due to preimage resistance.

// Batch verification equation (conceptually):
// Verify: sum_i(r^i * proof_i) == sum_i(r^i * (commitment_i evaluated at coset_i))
// using a single pairing check.
// For forgery: attacker needs sum_i(r^i * error_i) == 0 where error_i = (forged_proof_i - correct_proof_i)
// Requires r to be a root of the polynomial sum_i(x^i * error_i), probability ~2^{-254} for random r.
